  2	   views/run-log.js — Orchestrator Run Log Viewer
  3	   Section 4e of the MCP Server Dashboard SPA
  4	
  5	   Depends on: API, Router, escapeHtml, formatDate, showLoading, showError
  6	   ============================================================ */
  7	
  8	/* ----------------------------------------------------------
  9	   Event card renderers
 10	   ---------------------------------------------------------- */
 11	
 12	/**
 13	 * Returns a CSS severity class for an event action type.
 14	 *
 15	 * - error / fail actions → run-event--error
 16	 * - warning-ish          → run-event--warning
 17	 * - success outcomes     → run-event--success
 18	 * - default              → run-event--info
 19	 */
 20	function runEventSeverity(action) {
 21	  if (action === 'run_error' || action === 'stage_error' || action === 'halted_repeated_failure') return 'run-event--error';
 22	  if (action === 'safety_limit' || action === 'rework_detected' || action === 'mcp_error' || action === 'dry_run_no_ledger') return 'run-event--warning';
 23	  if (action === 'wp_complete' || action === 'run_end' || action === 'dry_run_complete') return 'run-event--success';
 24	  if (action === 'tool_call') return 'run-event--debug';
 25	  return 'run-event--info';
 26	}
 27	
 28	/**
 29	 * Formats a duration in seconds to a human-readable string.
 30	 * @param {number|null|undefined} sec - Duration in seconds.
 31	 * @returns {string} Formatted string (e.g. "3m 24s") or empty string.
 32	 */
 33	function formatDurationSec(sec) {
 34	  if (sec == null || isNaN(sec)) return '';
 35	  return formatDuration(sec * 1000);
 36	}
 37	
 38	/**
 39	 * Formats a token count to a compact human-readable string (e.g. "72k").
 40	 * @param {object|number|null} tokens - Token usage object or raw number.
 41	 * @returns {string} Formatted string or empty string.
 42	 */
 43	function formatTokens(tokens) {
 44	  if (tokens == null) return '';
 45	  var total = typeof tokens === 'number' ? tokens : (tokens.total_tokens || 0);
 46	  if (!total) return '';
 47	  if (total >= 1000) return Math.round(total / 1000) + 'k tokens';
 48	  return total + ' tokens';
 49	}
 50	
 51	/**
 52	 * Builds the inner content HTML for a single event entry.
 53	 * Handles known action types explicitly; falls back to a generic card.
 54	 *
 55	 * @param {object} entry - A parsed log entry object.
 56	 * @returns {string} HTML string for the card body.
 57	 */
 58	function buildRunEventContent(entry) {
 59	  const action = entry && entry.action ? String(entry.action) : 'unknown';
 60	
 61	  switch (action) {
 62	
 63	    // ── Orchestrator lifecycle ───────────────────────────────────────
 64	    case 'run_start': {
 65	      const threadId = entry.thread_id ? escapeHtml(String(entry.thread_id)) : '';
 66	      const plan = entry.plan ? String(entry.plan) : '';
 67	      // Show just the plan filename, not the full path
 68	      const planName = plan ? escapeHtml(plan.split('/').pop() || plan) : '';
 69	      const dryRunBadge = entry.dry_run ? ' <span class="badge badge-dry-run">Dry Run</span>' : '';
 70	      let html = '<strong>Run started</strong>' + dryRunBadge;
 71	      if (planName) html += ' &mdash; ' + planName;
 72	      if (threadId) html += '<br><span class="text-muted monospace" style="font-size:11px">Thread: ' + threadId + '</span>';
 73	      return html;
 74	    }
 75	    case 'run_end': {
 76	      const dur = entry.total_duration_s != null ? formatDurationSec(entry.total_duration_s) : '';
 77	      return '<strong>Run completed</strong>' + (dur ? ' <span class="text-muted">(' + escapeHtml(dur) + ')</span>' : '');
 78	    }
 79	    case 'run_error': {
 80	      const errMsg = entry.error ? escapeHtml(String(entry.error)) : 'Unknown error';
 81	      return '<strong>Run error:</strong> ' + errMsg;
 82	    }
 83	
 84	    // ── Stage events ─────────────────────────────────────────────────
 85	    case 'stage_start': {
 86	      const wpId = entry.wp_id ? escapeHtml(String(entry.wp_id)) : '';
 87	      const stg = entry.stage ? escapeHtml(String(entry.stage).replace(/_/g, ' ')) : '';
 88	      const iter = entry.iteration ? ' <span class="text-muted">(iteration ' + escapeHtml(String(entry.iteration)) + ')</span>' : '';
 89	      return '<strong>Stage started</strong>' +
 90	        (stg ? ' &mdash; <em>' + stg + '</em>' : '') +
 91	        (wpId ? ' for <strong>' + wpId + '</strong>' : '') +
 92	        iter;
 93	    }
 94	    case 'stage_complete': {
 95	      const wpId = entry.wp_id ? escapeHtml(String(entry.wp_id)) : '';
 96	      const result = entry.result ? escapeHtml(String(entry.result)) : '';
 97	      const dur = formatDurationSec(entry.duration_s);
 98	      const tok = formatTokens(entry.tokens_used);
 99	      const details = [];
100	      if (dur) details.push(dur);

301	      if (!genericMsg && entry.error) genericMsg = ': ' + escapeHtml(String(entry.error));
302	      if (!genericMsg && entry.reason) genericMsg = ': ' + escapeHtml(String(entry.reason));
303	      return '<strong>' + escapeHtml(action) + '</strong>' + genericMsg;
304	    }
305	  }
306	}
307	
308	/**
309	 * Builds the full HTML for a single run event card.
310	 *
311	 * @param {object} entry - A parsed log entry.
312	 * @returns {string} HTML string.
313	 */
314	function buildRunEventCard(entry) {
315	  var action = entry && entry.action ? String(entry.action) : 'unknown';
316	  var severityClass = runEventSeverity(action);
317	
318	  // Stage badge — use entry.stage or entry.action as fallback label
319	  var stageLabel = entry.stage
320	    ? escapeHtml(String(entry.stage).replace(/_/g, ' '))
321	    : escapeHtml(action.replace(/_/g, ' '));
322	  var stageBadge = '<span class="run-stage-badge">' + stageLabel + '</span>';
323	
324	  // WP ID badge (when present)
325	  var wpBadge = '';
326	  if (entry.wp_id) {
327	    wpBadge = '<span class="run-wp-badge">' + escapeHtml(String(entry.wp_id)) + '</span>';
328	  }
329	
330	  // Timestamp
331	  var ts = entry.timestamp ? escapeHtml(formatDate(String(entry.timestamp))) : '';
332	
333	  return '<div class="run-event ' + severityClass + '">' +
334	    '<div style="display:flex;align-items:center;gap:8px;margin-bottom:4px;flex-wrap:wrap">' +
335	      stageBadge +
336	      wpBadge +
337	      (ts ? '<span class="text-muted" style="font-size:11px">' + ts + '</span>' : '') +
338	    '</div>' +
339	    '<div>' + buildRunEventContent(entry) + '</div>' +
340	  '</div>';
341	}
